import {recipes, ingredients, matchRecipe, filterRecipes, totalTime} from './recipes.js';
import {mountVideo, destroyVideo} from './video.js';
const $=s=>document.querySelector(s);
const read=(key,fallback)=>{try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback;}catch{return fallback;}};
const equipmentNames=['Stovetop','Oven','Air fryer','Microwave','Blender','Food processor','Slow cooker','Grill'];
const state={pantry:read('pp-pantry',[]).filter(i=>ingredients.includes(i)),equipment:read('pp-equipment',[]).filter(e=>equipmentNames.includes(e)),saved:read('pp-saved',[]),time:9999,calories:9999,category:'Easy meals',sort:'relevant',query:'',onlyHave:false,page:'discover',visible:18};
const icons={clock:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',fire:'<svg viewBox="0 0 24 24"><path d="M13 3c1 6 7 7 7 12a8 8 0 0 1-16 0c0-3 2-5 4-7 0 3 2 4 3 4 2-2 2-5 2-9Z"/></svg>',bookmark:'<svg viewBox="0 0 24 24"><path d="M6 3h12v18l-6-4-6 4Z"/></svg>'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration=r=>!Number.isFinite(totalTime(r))?'Time not listed':totalTime(r)>=60?`${Math.floor(totalTime(r)/60)}h ${totalTime(r)%60||''}${totalTime(r)%60?'m':''}`:`${totalTime(r)} min`;
let toastTimer,activeRecipe=null,servings=1,completed=new Set(),checked=new Set(),returnRecipeId=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Storage is unavailable. Your changes will last for this visit.');}}
function renderPantry(){
 $('#pantry').innerHTML=state.pantry.map(i=>`<button class="chip selected" data-remove="${esc(i)}" aria-label="Remove ${esc(i)}">${esc(i)} <span aria-hidden="true">×</span></button>`).join('');
 $('#pantry-hint').hidden=state.pantry.length>0;
 $('#popular').innerHTML=['Chicken','Rice','Eggs','Tomato','Garlic','Spinach','Pasta','Chickpeas'].filter(i=>!state.pantry.includes(i)).map(i=>`<button class="chip" data-add="${i}">${i} <span aria-hidden="true">+</span></button>`).join('');
 $('#equipment').innerHTML=equipmentNames.map(e=>`<button class="chip ${state.equipment.includes(e)?'selected':''}" data-equipment="${e}" aria-pressed="${state.equipment.includes(e)}">${e}</button>`).join('');
}
function render(resetPage=true){
 if(resetPage)state.visible=18;renderPantry();const saved=state.page==='saved';
 $('#results-title').textContent=saved?'Your own little cookbook':state.pantry.length?'Good things from your kitchen':'A little inspiration for today';
 $('#results-subtitle').textContent=saved?'The recipes you’ll want to come back to.':state.pantry.length?'Sorted by the ingredients you already have.':`${recipes.length} checked recipes. Simple meals, real food photographs.`;
 $('#saved-count').textContent=state.saved.filter(id=>recipes.some(r=>r.id===id)).length||'';
 document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-pressed',String(b.dataset.page===state.page));});
 $('.categories').innerHTML=['Easy meals','All recipes','Asian','Quick & easy','Vegetarian','High protein','With video'].map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('');
 const list=filterRecipes(saved?recipes.filter(r=>state.saved.includes(r.id)):recipes,state);
 $('#result-count').textContent=`${list.length} ${list.length===1?'recipe':'recipes'}${state.pantry.length?' matched':''}`;
 $('#data-note').hidden=false;
 $('#data-note').textContent='Every recipe includes prep and cooking times. Calories and protein are estimates per serving; portion sizes are shown in each recipe.';
 $('#recipe-grid').innerHTML=list.length?list.slice(0,state.visible).map(recipeCard).join(''):`<div class="empty"><span class="empty-symbol" aria-hidden="true">♧</span><h3>${saved&&!state.saved.length?'Your cookbook starts here':'No recipes just yet'}</h3><p>${saved&&!state.saved.length?'Tap the bookmark on a recipe to keep it here.':'Try a little more time, another ingredient, or fewer filters.'}</p><button class="primary" id="empty-reset">${saved&&!state.saved.length?'Explore recipes':'Clear filters'}</button></div>`;
 $('#load-more').hidden=list.length<=state.visible;$('#load-more').textContent=`Show ${Math.min(18,Math.max(0,list.length-state.visible))} more recipes`;
}
function recipeCard(r){
 const m=matchRecipe(r,state.pantry),saved=state.saved.includes(r.id);
 return `<article class="recipe-card"><div class="card-image"><button class="photo-button" data-recipe="${r.id}" aria-label="View ${esc(r.title)}"><img class="food-photo" src="${esc(r.image)}" alt="${esc(r.title)}" loading="lazy" decoding="async" width="480" height="320"></button><button class="icon-button bookmark ${saved?'saved':''}" data-save="${r.id}" aria-label="${saved?'Unsave':'Save'} ${esc(r.title)}" aria-pressed="${saved}">${icons.bookmark}</button></div><div class="card-content"><button class="recipe-title" data-recipe="${r.id}">${esc(r.title)}</button><div class="recipe-meta"><span>Prep <strong>${r.prep} min</strong></span><span>Cook <strong>${r.cook} min</strong></span><span>Calories <strong>${r.kcal} kcal</strong></span><span>Protein <strong>${r.protein} g</strong></span></div><p class="card-portion">Nutrition per serving · Serves ${r.servings}${r.wait?` · +${r.wait} min ${esc((r.waitLabel||'waiting').toLowerCase())}`:''}</p><p class="match">${state.pantry.length?m.missing.length?`<strong>${m.have} of ${m.total}</strong> ingredients in your kitchen`:'<strong>Everything you need is in your kitchen</strong>':`${r.easy?'Easy':'More time & steps'} · ${esc(r.area||'Everyday cooking')}`}</p></div></article>`;
}
function addIngredient(i){if(!ingredients.includes(i)||state.pantry.includes(i))return;state.pantry.push(i);persist('pp-pantry',state.pantry);$('#ingredient-search').value='';hideSuggestions();render();}
function hideSuggestions(){$('#suggestions').hidden=true;$('#ingredient-search').setAttribute('aria-expanded','false');}
function suggestions(){const q=$('#ingredient-search').value.trim().toLowerCase();const matches=ingredients.filter(i=>!state.pantry.includes(i)&&i.toLowerCase().includes(q));$('#suggestions').hidden=!q;$('#ingredient-search').setAttribute('aria-expanded',String(!!q));$('#suggestions').innerHTML=matches.length?matches.slice(0,10).map(i=>`<button data-add="${esc(i)}">${esc(i)} <span>+</span></button>`).join(''):'<p>No matching ingredient in this collection.</p>';}
function reset(){Object.assign(state,{pantry:[],equipment:[],time:9999,calories:9999,category:'Easy meals',sort:'relevant',query:'',onlyHave:false});persist('pp-pantry',[]);persist('pp-equipment',[]);$('#time').value='9999';$('#calories').value='9999';$('#sort').value='relevant';$('#only-have').checked=false;$('#recipe-search').value='';$('#ingredient-search').value='';hideSuggestions();render();}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(s=>s!==id):[...state.saved,id];persist('pp-saved',state.saved);render(false);if(activeRecipe){const b=$('#recipe-dialog [data-save]');b.textContent=state.saved.includes(id)?'Saved to cookbook':'Save recipe';b.setAttribute('aria-pressed',String(state.saved.includes(id)));}toast(state.saved.includes(id)?'Recipe added to your cookbook':'Recipe removed from your cookbook');}
const quantity=n=>Number.isInteger(n)?n:Number(n.toFixed(2));
function renderIngredientList(){$('#detail-ingredients').innerHTML=activeRecipe.ingredients.map(([name,n,unit,originalName],i)=>`<li><label><input type="checkbox" data-check="${i}" ${checked.has(i)?'checked':''}><span>${n==null?esc(unit):`${quantity(n*servings)} ${esc(unit)}`} <strong>${esc((originalName||name).toLowerCase())}</strong>${state.pantry.includes(name)?'<small>In your kitchen</small>':''}</span></label></li>`).join('');}
function renderDetail(){
 const r=activeRecipe,m=matchRecipe(r,state.pantry);
 const equipment=r.equipment===null?'Check equipment in the method':r.equipment.length?r.equipment.join(' + '):'No cooking equipment needed';
 $('#recipe-detail').innerHTML=`<img class="detail-photo food-photo" src="${esc(r.image)}" alt="${esc(r.title)}" width="900" height="450"><div class="detail-body"><p class="photo-credit">Food photograph: <a href="${esc(r.photoSource)}" target="_blank" rel="noopener noreferrer">${esc(r.photoCredit)}</a></p><p class="detail-category">${r.easy?'Easy to cook':'More time & steps'} · ${esc(r.category)} · ${esc(equipment)}${r.equipmentInferred?' (from the method)':''}</p><h2 id="detail-title">${esc(r.title)}</h2><p class="detail-description">${esc(r.description)}</p><div class="detail-stats"><span><strong>${r.prep==null?'Not listed':`${r.prep} min`}</strong>Prep</span><span><strong>${r.cook==null?'Not listed':`${r.cook} min`}</strong>Cook</span>${r.wait?`<span><strong>${r.wait} min</strong>${esc(r.waitLabel||'Wait')}</span>`:''}<span><strong>${r.kcal==null?'Not listed':`${r.kcal} kcal`}</strong>Calories / serving</span><span><strong>${r.protein==null?'Not listed':`${r.protein} g`}</strong>Protein / serving</span></div><p class="timing-note">Total time: ${duration(r)}${r.wait?`, including ${r.wait} min waiting`: ''}. ${esc(r.timingNote)}</p><div class="detail-actions">${r.sourceQuantities?`<p class="source-quantities">Makes ${r.servings} servings<br><small>Ingredient quantities below are for the whole recipe.</small></p>`:'<div class="servings"><span>Servings</span><button data-servings="-1" aria-label="Fewer servings" disabled>−</button><output id="serving-output">1</output><button data-servings="1" aria-label="More servings">+</button></div>'}<button class="secondary" data-save="${r.id}" aria-pressed="${state.saved.includes(r.id)}">${state.saved.includes(r.id)?'Saved to cookbook':'Save recipe'}</button><button class="secondary jump-video" data-jump-video>▶ Watch tutorial</button></div><div class="detail-columns"><section><h3>What you’ll need</h3><p class="hint">${m.have} of ${m.total} main ingredients in your kitchen</p><ul class="ingredient-list" id="detail-ingredients"></ul><p class="hint">Salt, pepper, water and oil are treated as pantry basics. Check the listed ingredient variety before cooking.</p></section><section><h3>Let’s make it</h3><p class="hint" id="step-progress">0 of ${r.steps.length} steps complete</p><ol class="steps">${r.steps.map(([title,text],i)=>`<li><button class="step-number" data-step="${i}" aria-label="Complete: ${esc(title)}" aria-pressed="false">${i+1}</button><div><h4>${esc(title)}</h4><p>${esc(text)}</p></div></li>`).join('')}</ol></section></div><section class="video-section" id="video-section" aria-labelledby="video-heading"><div class="video-heading"><div><h3 id="video-heading">Cook along, right here</h3><p>${esc(r.videoNote||'Watch the tutorial without leaving your recipe.')}</p></div><span class="host-label">YouTube player</span></div><div id="video-mount"><button class="video-poster" data-play-video aria-label="Play tutorial for ${esc(r.title)}"><img src="${esc(r.image)}" alt="" loading="lazy"><span class="play-circle" aria-hidden="true">▶</span><span class="play-label">Play cooking tutorial</span></button></div><p id="video-status" class="video-status" role="status">Press play to load the video here. Internet access is required.</p><button id="retry-video" class="secondary" data-play-video hidden>Try loading video again</button></section>${r.sourceUrl?`<p class="recipe-source">Recipe and photograph courtesy of <a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">TheMealDB community</a>.${r.originalSource?` <a href="${esc(r.originalSource)}" target="_blank" rel="noopener noreferrer">Original recipe source</a>.`: ''}</p>`:''}${r.reviewNotes?.length?`<details class="review-notes"><summary>Recipe notes</summary><ul>${r.reviewNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></details>`:''}<p class="nutrition-note">${esc(r.nutritionNote)} <a href="${esc(r.nutritionSource)}" target="_blank" rel="noopener noreferrer">${r.nutritionKind==='publisher'?'Good Food nutrition source':'USDA nutrition reference'}</a>. Check ingredient labels for allergens.</p></div>`;
 renderIngredientList();
}
function openRecipe(id){const r=recipes.find(r=>r.id===id);if(!r)return;destroyVideo();activeRecipe=r;returnRecipeId=id;servings=1;completed=new Set();checked=new Set();renderDetail();$('#recipe-dialog').showModal();$('#recipe-dialog').scrollTop=0;document.body.classList.add('modal-open');$('#close-dialog').focus();}
function changeServings(delta){servings=Math.max(1,Math.min(8,servings+delta));$('#serving-output').textContent=servings;$('#recipe-dialog [data-servings="-1"]').disabled=servings===1;$('#recipe-dialog [data-servings="1"]').disabled=servings===8;renderIngredientList();}
function completeStep(button){const i=Number(button.dataset.step);completed.has(i)?completed.delete(i):completed.add(i);const done=completed.has(i);button.closest('li').classList.toggle('done',done);button.textContent=done?'✓':i+1;button.setAttribute('aria-pressed',String(done));button.setAttribute('aria-label',`${done?'Mark incomplete':'Complete'}: ${activeRecipe.steps[i][0]}`);$('#step-progress').textContent=`${completed.size} of ${activeRecipe.steps.length} steps complete`;if(completed.size===activeRecipe.steps.length)toast('All done. Enjoy your meal!');}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.add)addIngredient(d.add);
 if(d.remove){state.pantry=state.pantry.filter(i=>i!==d.remove);persist('pp-pantry',state.pantry);render();}
 if(d.equipment){state.equipment=state.equipment.includes(d.equipment)?state.equipment.filter(i=>i!==d.equipment):[...state.equipment,d.equipment];persist('pp-equipment',state.equipment);render();}
 if(d.category){state.category=d.category;render();}
 if(d.page){state.page=d.page;render();if(d.page==='saved')$('.results').scrollIntoView({behavior:'smooth',block:'start'});}
 if(d.recipe)openRecipe(d.recipe);if(d.save)save(d.save);
 if(d.servings)changeServings(Number(d.servings));if(d.step!==undefined)completeStep(b);
 if(d.jumpVideo!==undefined)$('#video-section').scrollIntoView({behavior:'smooth',block:'start'});
 if(d.playVideo!==undefined&&activeRecipe)mountVideo(activeRecipe.videoId,activeRecipe.title);
 if(b.id==='empty-reset'){reset();state.page='discover';render();}
});
document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement){event.target.classList.add('photo-unavailable');event.target.alt='Photo unavailable';}},true);
$('#recipe-dialog').addEventListener('change',e=>{if(e.target.dataset.check!==undefined){const i=Number(e.target.dataset.check);e.target.checked?checked.add(i):checked.delete(i);}});
$('#close-dialog').onclick=()=>$('#recipe-dialog').close();
$('#recipe-dialog').addEventListener('close',()=>{destroyVideo();$('#video-mount')?.replaceChildren();document.body.classList.remove('modal-open');activeRecipe=null;document.querySelector(`[data-recipe="${returnRecipeId}"]`)?.focus();});
$('#recipe-dialog').addEventListener('click',e=>{if(e.target===$('#recipe-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#ingredient-search').addEventListener('input',suggestions);$('#ingredient-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const b=$('#suggestions button');if(!$('#suggestions').hidden&&b)addIngredient(b.dataset.add);}if(e.key==='Escape')hideSuggestions();});
document.addEventListener('click',e=>{if(!e.target.closest('.search-field')&&!e.target.closest('#suggestions'))hideSuggestions();});
for(const id of ['time','calories','sort'])$('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render();});
$('#only-have').addEventListener('change',e=>{state.onlyHave=e.target.checked;render();});
$('#recipe-search').addEventListener('input',e=>{state.query=e.target.value;render();});
$('#reset').onclick=reset;$('#find').onclick=()=>{render();$('.results').scrollIntoView({behavior:'smooth',block:'start'});toast($('#result-count').textContent);};
$('#load-more').onclick=()=>{state.visible+=18;render(false);};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
